problems.solution:
class MedianFinder:
    def __init__(self):
        self.left = []    # max-heap (stored negated): the smaller half
        self.right = []   # min-heap: the larger half

    def add_num(self, x):
        if not self.left or x <= -self.left[0]:
            heapq.heappush(self.left, -x)
        else:
            heapq.heappush(self.right, x)
        # rebalance so that len(left) == len(right) or len(left) == len(right) + 1
        if len(self.left) > len(self.right) + 1:
            heapq.heappush(self.right, -heapq.heappop(self.left))
        elif len(self.right) > len(self.left):
            heapq.heappush(self.left, -heapq.heappop(self.right))

    def find_median(self):
        if len(self.left) > len(self.right):
            return -self.left[0]
        return (-self.left[0] + self.right[0]) / 2

