def last_stone_weight(stones):
    heap = [-x for x in stones]           # max-heap via negation
    heapq.heapify(heap)
    while len(heap) > 1:
        x = -heapq.heappop(heap)          # heaviest
        y = -heapq.heappop(heap)          # second heaviest
        if x != y:
            heapq.heappush(heap, -(x - y))
    return -heap[0] if heap else 0

