    heap = []                                           # max-heap of profits of affordable projects
    i = 0
    for _ in range(k):
        while i < len(projects) and projects[i][0] <= w:
            _, profit = projects[i]
            heapq.heappush(heap, -profit)
            i += 1
        if not heap:
            break
        w += -heapq.heappop(heap)                       # take the most profitable one
