problems.solution:
def furthest_building(heights, bricks, ladders):
    """Min-heap of size <= ladders keeps the LARGEST climbs (they get the ladders);
    every climb pushed out of the heap has to be paid for with bricks."""
    heap = []
    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb <= 0:
            continue
        heapq.heappush(heap, climb)
        if len(heap) > ladders:
            bricks -= heapq.heappop(heap)     # smallest climb among the ladder-holders -> bricks
        if bricks < 0:
            return i
    return len(heights) - 1

