def min_cost_to_hire(quality, wage, k):
    workers = sorted(zip(quality, wage), key=lambda x: x[1] / x[0])   # by wage/quality ratio
    max_heap = []                         # negated qualities of the current group
    quality_sum = 0
    answer = float('inf')
    for q, w in workers:
        heapq.heappush(max_heap, -q)
        quality_sum += q
        if len(max_heap) > k:
            quality_sum += heapq.heappop(max_heap)   # popped value is negative: removes the largest quality
        if len(max_heap) == k:
            answer = min(answer, (w / q) * quality_sum)
    return answer

