def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:                                   # a closing bracket
            if not stack or stack[-1] != pairs[ch]:
                return False                              # nothing to match, or the wrong kind on top
            stack.pop()
        else:                                             # an opening bracket
            stack.append(ch)
    return not stack                                      # leftovers = unmatched openers

