def asteroid_collision(asteroids):
    stack = []
    for a in asteroids:
        alive = True
        while alive and a < 0 and stack and stack[-1] > 0:      # right-mover on top meets a left-mover
            if stack[-1] < -a:
                stack.pop()                                     # the top explodes, keep checking
            elif stack[-1] == -a:
                stack.pop()
                alive = False                                   # both explode
            else:
                alive = False                                   # the newcomer explodes
        if alive:
            stack.append(a)
    return stack

