def calculate_ii(s):
    """'3+2*2' -> 7 ; + - * / on non-negative integers, no parentheses."""
    stack = []
    num = 0
    op = '+'                                                    # the operator that came BEFORE `num`
    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num * 10 + int(ch)
        if ch in '+-*/' or i == len(s) - 1:
            if op == '+':
                stack.append(num)
            elif op == '-':
                stack.append(-num)
            elif op == '*':
                stack.append(stack.pop() * num)                 # * and / bind tighter: fold into the last term
            elif op == '/':
                stack.append(int(stack.pop() / num))
            op = ch
            num = 0
    return sum(stack)

