class MinStack:
    """push/pop/top/get_min all in O(1).  Each entry remembers the minimum at the time it was pushed."""

    def __init__(self):
        self.stack = []                                         # (value, min_so_far)

    def push(self, x):
        cur_min = x if not self.stack else min(x, self.stack[-1][1])
        self.stack.append((x, cur_min))

    def pop(self):
        return self.stack.pop()[0]

    def top(self):
        return self.stack[-1][0]

    def get_min(self):
        return self.stack[-1][1]

