class QueueUsingStacks:
    """FIFO queue from two LIFO stacks: amortized O(1) per operation."""

    def __init__(self):
        self.inbox = []                                         # new items are pushed here
        self.outbox = []                                        # items are popped from here (oldest on top)

    def push(self, x):
        self.inbox.append(x)

    def _move(self):
        if not self.outbox:                                     # only refill when the outbox is EMPTY
            while self.inbox:
                self.outbox.append(self.inbox.pop())            # reverses the order: oldest ends on top

    def pop(self):
        self._move()
        return self.outbox.pop()

    def peek(self):
        self._move()
        return self.outbox[-1]

    def empty(self):
        return not self.inbox and not self.outbox

