def next_greater_circular(nums):
    """503: the array is circular -> scan it twice (2n) but only push each index once."""
    n = len(nums)
    ans = [-1] * n
    stack = []
    for i in range(2 * n):
        x = nums[i % n]
        while stack and x > nums[stack[-1]]:
            ans[stack.pop()] = x
        if i < n:
            stack.append(i)
    return ans

