class StockSpanner:
    """901: span = number of consecutive days (ending today) with price <= today's price."""

    def __init__(self):
        self.stack = []                                         # (price, span), prices strictly decreasing

    def next(self, price):
        span = 1
        while self.stack and self.stack[-1][0] <= price:
            span += self.stack.pop()[1]                         # absorb the span of every smaller-or-equal day
        self.stack.append((price, span))
        return span

