def remove_duplicate_letters(s):
    last = {c: i for i, c in enumerate(s)}                      # last position of every letter
    stack, seen = [], set()
    for i, c in enumerate(s):
        if c in seen:
            continue
        while stack and stack[-1] > c and last[stack[-1]] > i:  # top is bigger AND appears again later
            seen.discard(stack.pop())
        stack.append(c)
        seen.add(c)
    return ''.join(stack)

