def trap_rain_water(height):
    stack = []                                                  # indices of a decreasing sequence of walls
    water = 0
    for i, h in enumerate(height):
        while stack and h > height[stack[-1]]:
            bottom = height[stack.pop()]                        # the "floor" of a pool
            if not stack:
                break                                           # no left wall: water would run out
            width = i - stack[-1] - 1
            bounded = min(h, height[stack[-1]]) - bottom        # water level minus the floor
            water += width * bounded
        stack.append(i)
    return water

